"use strict";(self.webpackChunkintegrated_retail_kb=self.webpackChunkintegrated_retail_kb||[]).push([["3483"],{5078(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>s,contentTitle:()=>a,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"legal-policies/non-disclosure-agreement-nda-66","title":"Non-Disclosure Agreement (NDA)","description":"(1) INTEGRATED RETAIL PTE LTD, incorporated in Singapore (UEN 200602440C), of 26 Sin Ming Lane, #04-114, Midview City, Singapore 573971 (\\"IR\\"); and","source":"@site/docs/legal-policies/non-disclosure-agreement-nda-66.md","sourceDirName":"legal-policies","slug":"/legal-policies/non-disclosure-agreement-nda","permalink":"/docs/legal-policies/non-disclosure-agreement-nda","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"non-disclosure-agreement-nda-66","title":"Non-Disclosure Agreement (NDA)","slug":"/legal-policies/non-disclosure-agreement-nda","description":"(1) INTEGRATED RETAIL PTE LTD, incorporated in Singapore (UEN 200602440C), of 26 Sin Ming Lane, #04-114, Midview City, Singapore 573971 (\\"IR\\"); and"},"sidebar":"tutorialSidebar","previous":{"title":"Master Service Agreement","permalink":"/docs/legal-policies/master-service-agreement"},"next":{"title":"Password Policy","permalink":"/docs/legal-policies/password-policy"}}'),r=i(4848),o=i(8453);let s={id:"non-disclosure-agreement-nda-66",title:"Non-Disclosure Agreement (NDA)",slug:"/legal-policies/non-disclosure-agreement-nda",description:'(1) INTEGRATED RETAIL PTE LTD, incorporated in Singapore (UEN 200602440C), of 26 Sin Ming Lane, #04-114, Midview City, Singapore 573971 ("IR"); and'},a="1. CONFIDENTIAL INFORMATION",l={},c=[];function d(e){let n={h1:"h1",header:"header",hr:"hr",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.p,{children:"MUTUAL NON-DISCLOSURE AGREEMENT"}),"\n",(0,r.jsx)(n.p,{children:"\xa0"}),"\n",(0,r.jsx)(n.p,{children:"THIS AGREEMENT is made on [DATE] between:"}),"\n",(0,r.jsx)(n.p,{children:'(1) INTEGRATED RETAIL PTE LTD, incorporated in Singapore (UEN 200602440C), of 26 Sin Ming Lane, #04-114, Midview City, Singapore 573971 ("IR"); and'}),"\n",(0,r.jsx)(n.p,{children:'(2) [CUSTOMER LEGAL NAME], incorporated in [COUNTRY] (registration number [REG. NO.]), of [REGISTERED ADDRESS] (the "Customer"),'}),"\n",(0,r.jsx)(n.p,{children:'each a "Party" and together the "Parties".'}),"\n",(0,r.jsx)(n.p,{children:'IR supplies software and technology solutions and related services to retail and consumer businesses. The Parties wish to exchange information so that IR may assess the Customer\u2019s requirements and propose, deliver, support and extend such solutions for the Customer (the "Purpose"). This Agreement sets out how each Party will protect the information the other discloses to it for the Purpose. It applies equally to both Parties.'}),"\n",(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"1-confidential-information",children:"1. CONFIDENTIAL INFORMATION"})}),"\n",(0,r.jsx)(n.p,{children:'1.1 "Confidential Information" means any information, in any form, disclosed by one Party (the "Discloser") to the other (the "Recipient") in connection with the Purpose, which is identified as confidential or which a reasonable person would understand to be confidential. It includes each Party\u2019s business, commercial, financial, technical and operational information, its systems, software, configurations, credentials and data, its pricing and terms, and the existence and contents of this Agreement.'}),"\n",(0,r.jsx)(n.p,{children:'1.2 "Representatives" means a Party\u2019s employees, officers, group companies, branches and offices in any country, and its advisers, contractors and subcontractors, in each case involved in the Purpose.'}),"\n",(0,r.jsx)(n.h1,{id:"2-obligations",children:"2. OBLIGATIONS"}),"\n",(0,r.jsx)(n.p,{children:"2.1 The Recipient shall keep the Confidential Information confidential, use it only for the Purpose, and protect it with at least reasonable care and appropriate security measures."}),"\n",(0,r.jsx)(n.p,{children:"2.2 The Recipient may disclose Confidential Information to its Representatives who need it for the Purpose, provided they are bound by confidentiality obligations no less protective than these. The Recipient remains responsible for their compliance."}),"\n",(0,r.jsx)(n.p,{children:"2.3 The Recipient may disclose Confidential Information where required by law, a court or a regulator, giving the Discloser prior notice where lawful and practicable and disclosing only what is required."}),"\n",(0,r.jsx)(n.p,{children:"2.4 The Recipient shall notify the Discloser without undue delay if it becomes aware of any unauthorised use, access or disclosure of the Confidential Information."}),"\n",(0,r.jsx)(n.h1,{id:"3-what-is-not-covered",children:"3. WHAT IS NOT COVERED"}),"\n",(0,r.jsx)(n.p,{children:"3.1 These obligations do not apply to information which the Recipient can show: (a) it already lawfully held free of any obligation of confidence; (b) is or becomes public other than through a breach; (c) it lawfully received from a third party without restriction; or (d) it developed independently without using the Discloser\u2019s Confidential Information."}),"\n",(0,r.jsx)(n.h1,{id:"4-how-long-this-lasts",children:"4. HOW LONG THIS LASTS"}),"\n",(0,r.jsx)(n.p,{children:"4.1 This Agreement takes effect on the date above and continues until either Party ends it by giving thirty (30) days\u2019 written notice. No renewal or other action is needed to keep it in force."}),"\n",(0,r.jsx)(n.p,{children:"4.2 For each item of Confidential Information, the obligations in this Agreement last for three (3) years from the date that item was disclosed, and continue to apply after this Agreement ends. Trade secrets remain protected for as long as they remain trade secrets, and personal data for as long as the Recipient holds it."}),"\n",(0,r.jsx)(n.h1,{id:"5-return-and-deletion",children:"5. RETURN AND DELETION"}),"\n",(0,r.jsx)(n.p,{children:"5.1 On the Discloser\u2019s written request, or when this Agreement ends, the Recipient shall return or securely destroy the Confidential Information and confirm in writing that it has done so. The Recipient may keep copies it is required to keep by law or which remain in routine backups; those copies stay subject to this Agreement."}),"\n",(0,r.jsx)(n.h1,{id:"6-personal-data",children:"6. PERSONAL DATA"}),"\n",(0,r.jsx)(n.p,{children:"6.1 Where Confidential Information includes personal data, each Party shall comply with applicable data protection law. The Discloser shall disclose only the personal data necessary for the Purpose and shall have a lawful basis for doing so. The Recipient shall use it only for the Purpose and keep it secure."}),"\n",(0,r.jsx)(n.p,{children:"6.2 Any processing of personal data by IR in the course of delivering a solution to the Customer shall be governed by a separate data processing agreement."}),"\n",(0,r.jsx)(n.h1,{id:"7-no-rights-or-commitments-created",children:"7. NO RIGHTS OR COMMITMENTS CREATED"}),"\n",(0,r.jsx)(n.p,{children:'7.1 Confidential Information remains the Discloser\u2019s property. No licence or other right in it, or in any intellectual property, is granted except the right to use it for the Purpose. Confidential Information is provided "as is", with no warranty as to its accuracy or completeness.'}),"\n",(0,r.jsx)(n.p,{children:"7.2 This Agreement does not require either Party to disclose anything, to proceed with any transaction, or to refrain from doing business with anyone else, and does not create any partnership or agency between them."}),"\n",(0,r.jsx)(n.p,{children:"7.3 Where the Parties sign a further agreement for the supply of solutions or services which contains its own confidentiality terms, those terms apply to information disclosed under it and this Agreement continues to apply to everything else."}),"\n",(0,r.jsx)(n.h1,{id:"8-use-of-names",children:"8. USE OF NAMES"}),"\n",(0,r.jsx)(n.p,{children:"8.1 Neither Party shall announce this Agreement or the Purpose publicly, or use the other Party\u2019s name or logo in any publicity, without the other Party\u2019s prior written consent. Consent need only be given once and then covers later use of the same kind, until withdrawn by written notice."}),"\n",(0,r.jsx)(n.p,{children:"8.2 Optional: the Customer [ GRANTS / DOES NOT GRANT ] consent for IR to identify it by name and logo as a customer of IR. If left blank, consent is not given."}),"\n",(0,r.jsx)(n.h1,{id:"9-remedies",children:"9. REMEDIES"}),"\n",(0,r.jsx)(n.p,{children:"9.1 Damages alone may not be an adequate remedy for a breach of this Agreement, and either Party may seek injunctive or other equitable relief for an actual or threatened breach, in addition to any other remedy."}),"\n",(0,r.jsx)(n.h1,{id:"10-general",children:"10. GENERAL"}),"\n",(0,r.jsx)(n.p,{children:"10.1 Notices shall be in writing, sent to the recipient Party\u2019s registered address above or by email to its usual business contact, and are effective on acknowledgement of receipt."}),"\n",(0,r.jsx)(n.p,{children:"10.2 This Agreement is the entire agreement between the Parties on its subject matter. It may only be varied in writing signed by both Parties, and neither Party may assign it without the other\u2019s consent, except to a group company or a successor to its business."}),"\n",(0,r.jsx)(n.p,{children:"10.3 If any provision is unenforceable, it shall apply with the minimum modification necessary or be deleted, and the rest of this Agreement continues in force. A delay in enforcing a right is not a waiver of it. No one other than the Parties may enforce this Agreement."}),"\n",(0,r.jsx)(n.p,{children:"10.4 This Agreement may be signed in counterparts, and signatures sent electronically or applied by electronic signature are valid and binding."}),"\n",(0,r.jsx)(n.p,{children:"10.5 This Agreement is written in English. Where local law requires a local-language version, the Parties shall sign a bilingual version and the English version prevails so far as the law allows."}),"\n",(0,r.jsx)(n.h1,{id:"11-governing-law",children:"11. GOVERNING LAW"}),"\n",(0,r.jsx)(n.p,{children:"11.1 This Agreement is governed by the laws of Singapore, and the Parties submit to the exclusive jurisdiction of the Singapore courts, except that either Party may seek interim relief in any competent court."}),"\n",(0,r.jsx)(n.p,{children:"\xa0"}),"\n",(0,r.jsx)(n.p,{children:"Signed by duly authorised representatives of the Parties:"}),"\n",(0,r.jsx)(n.p,{children:"For and on behalf of IR"}),"\n",(0,r.jsx)(n.p,{children:"INTEGRATED RETAIL PTE LTD"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Signature"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Name"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Title"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Date"}),"\n",(0,r.jsx)(n.p,{children:"For and on behalf of the Customer"}),"\n",(0,r.jsx)(n.p,{children:"[CUSTOMER LEGAL NAME]"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Signature"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Name"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Title"}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"Date"}),"\n",(0,r.jsx)(n.p,{children:"\xa0"})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>s,x:()=>a});var t=i(6540);let r={},o=t.createContext(r);function s(e){let n=t.useContext(o);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),t.createElement(o.Provider,{value:n},e.children)}}}]);